// Convert a Stripe event into one row with a fixed shape
const e = $input.first().json;
const o = (e.data && e.data.object) || {};
const email = (o.customer_details && o.customer_details.email)
  || (o.billing_details && o.billing_details.email)
  || o.receipt_email || 'unknown';
const map = {
  'checkout.session.completed': { amount: o.amount_total, status: 'completed' },
  'charge.failed': { amount: o.amount, status: 'failed' },
  'charge.refunded': { amount: o.amount_refunded, status: 'refunded' },
  'charge.dispute.created': { amount: o.amount, status: 'disputed' }
};
const m = map[e.type];
if (!m || !e.id) return [];
// Use Stripe's own event time, not the time n8n received it
const ts = e.created ? new Date(e.created * 1000) : new Date();
return [{ json: {
  event_id: e.id,
  event_type: e.type,
  amount: Number(m.amount || 0),
  currency: String(o.currency || '').toUpperCase(),
  customer_email: email,
  status: m.status,
  created_at: ts.toISOString()
} }];

// ---- Settings (amounts in the smallest currency unit) ----
const BASELINE_DAYS = 30;      // history window for the baseline
const MIN_SAMPLES = 10;        // below this, use the fixed threshold instead
const Z_THRESHOLD = 3;         // standard deviations above the average
const FIXED_THRESHOLD = 10000; // 10000 = 100.00
const FAIL_WINDOW_MIN = 60;    // failed-payment spike window
const FAIL_SPIKE = 3;          // failures in the window, including this one
const REFUND_WINDOW_H = 24;    // refund spike window
const REFUND_SPIKE = 3;        // refunds in the window, including this one

const ev = $('Normalize Event').first().json;
const history = $input.all().map(i => i.json).filter(r => r.event_id);
const now = new Date(ev.created_at).getTime();
const within = ms => history.filter(r => {
  const t = new Date(r.created_at).getTime();
  return t >= now - ms && t <= now;
});
const money = (minor, cur) => (minor / 100).toFixed(2) + ' ' + cur;

const isDuplicate = history.some(r => r.event_id === ev.event_id);
const rank = { none: 0, warning: 1, critical: 2 };
let severity = 'none';
const reasons = [];
const raise = (level, text) => {
  reasons.push('[' + level.toUpperCase() + '] ' + text);
  if (rank[level] > rank[severity]) severity = level;
};

let baselineText = 'not used for this event type';
if (ev.status === 'completed') {
  const amounts = within(BASELINE_DAYS * 864e5)
    .filter(r => r.status === 'completed' && r.currency === ev.currency)
    .map(r => Number(r.amount));
  if (amounts.length >= MIN_SAMPLES) {
    const mean = amounts.reduce((a, b) => a + b, 0) / amounts.length;
    const sd = Math.max(Math.sqrt(amounts.reduce((a, b) => a + (b - mean) ** 2, 0) / amounts.length), 1);
    const z = (ev.amount - mean) / sd;
    baselineText = amounts.length + ' payments, average ' + money(mean, ev.currency) + ', z-score ' + z.toFixed(2);
    if (z >= Z_THRESHOLD) {
      raise('warning', 'Payment of ' + money(ev.amount, ev.currency) + ' is ' + z.toFixed(1)
        + ' standard deviations above your ' + BASELINE_DAYS + '-day average of ' + money(mean, ev.currency) + '.');
    }
  } else {
    baselineText = 'only ' + amounts.length + (amounts.length === 1 ? ' past payment' : ' past payments') + ' (needs ' + MIN_SAMPLES + '), fixed threshold used';
    if (ev.amount >= FIXED_THRESHOLD) {
      raise('warning', 'Payment of ' + money(ev.amount, ev.currency) + ' is at or above the fixed threshold of '
        + money(FIXED_THRESHOLD, ev.currency) + '.');
    }
  }
}

if (ev.status === 'failed') {
  const n = within(FAIL_WINDOW_MIN * 6e4).filter(r => r.status === 'failed').length + 1;
  if (n >= FAIL_SPIKE) {
    raise('critical', n + ' failed payments in the last ' + FAIL_WINDOW_MIN
      + ' minutes. Possible card-testing attack or a broken checkout.');
  }
}

if (ev.status === 'refunded') {
  const n = within(REFUND_WINDOW_H * 36e5).filter(r => r.status === 'refunded').length + 1;
  if (n >= REFUND_SPIKE) {
    raise('warning', n + ' refunds in the last ' + REFUND_WINDOW_H + ' hours.');
  }
}

if (ev.status === 'disputed') {
  raise('critical', 'A dispute was opened for ' + money(ev.amount, ev.currency)
    + '. Respond with evidence in your Stripe dashboard before the deadline.');
}

return [{ json: {
  ...ev,
  is_duplicate: isDuplicate ? 'yes' : 'no',
  alert: severity === 'none' ? 'no' : 'yes',
  severity,
  reasons: reasons.join('\n'),
  baseline_text: baselineText
} }];

// Keep only the Data Table columns
return $input.all().map(i => ({ json: {
  event_id: i.json.event_id,
  event_type: i.json.event_type,
  amount: i.json.amount,
  currency: i.json.currency,
  customer_email: i.json.customer_email,
  status: i.json.status,
  created_at: i.json.created_at
} }));

