const DAY = 864e5;
const now = Date.now();
const rows = $input.all().map(i => i.json).filter(r => r.event_id);
const range = (from, to) => rows.filter(r => {
  const t = new Date(r.created_at).getTime();
  return t >= from && t < to;
});
const sumBy = list => {
  const t = {};
  for (const r of list) { const c = r.currency || 'N/A'; t[c] = (t[c] || 0) + Number(r.amount || 0); }
  return t;
};
const money = t => {
  const k = Object.keys(t);
  return k.length ? k.map(c => (t[c] / 100).toFixed(2) + ' ' + c).join(', ') : '0.00';
};
const stats = list => {
  const by = s => list.filter(r => r.status === s);
  const done = by('completed'), failed = by('failed'), refunded = by('refunded'), disputed = by('disputed');
  const attempts = done.length + failed.length;
  return {
    revenue: sumBy(done), payments: done.length, failed: failed.length,
    refunds: refunded.length, refundTotal: sumBy(refunded), disputes: disputed.length,
    failRate: attempts ? failed.length / attempts * 100 : 0,
    refundRate: done.length ? refunded.length / done.length * 100 : 0
  };
};
const change = (a, b) => b ? ((a - b) / b * 100 >= 0 ? '+' : '') + ((a - b) / b * 100).toFixed(0) + '%' : (a ? 'up from zero' : 'no change');

const cur = stats(range(now - DAY, now));
const prev = stats(range(now - 2 * DAY, now - DAY));
const weekAvg = stats(range(now - 8 * DAY, now - DAY)).payments / 7;

const curKeys = Object.keys(cur.revenue);
const revenueChange = curKeys.map(c =>
  (curKeys.length > 1 ? c + ' ' : '') + change(cur.revenue[c], prev.revenue[c] || 0)).join(', ') || 'no change';

const flags = [];
if (cur.disputes) flags.push(cur.disputes + ' dispute(s) opened. Respond in your Stripe dashboard.');
if (cur.failed >= 3 && cur.failRate >= 20) flags.push('Failure rate is ' + cur.failRate.toFixed(1) + '%.');
if (cur.refunds >= 2 && cur.refundRate >= 10) flags.push('Refund rate is ' + cur.refundRate.toFixed(1) + '%.');
if (weekAvg >= 1 && cur.payments < weekAvg * 0.5) {
  flags.push('Payments (' + cur.payments + ') are less than half of the 7-day average (' + weekAvg.toFixed(1) + ' per day).');
}
const health = flags.length ? 'ATTENTION' : 'HEALTHY';

const line = (label, value) => label.padEnd(20) + value;
const report = [
  'Status: ' + health,
  '',
  'LAST 24 HOURS',
  line('Revenue:', money(cur.revenue) + '  (vs previous day: ' + revenueChange + ')'),
  line('Payments:', cur.payments + '  (previous day: ' + prev.payments + ', 7-day avg: ' + weekAvg.toFixed(1) + ')'),
  line('Failed payments:', cur.failed + '  (failure rate ' + cur.failRate.toFixed(1) + '%)'),
  line('Refunds:', cur.refunds + '  (' + money(cur.refundTotal) + ', refund rate ' + cur.refundRate.toFixed(1) + '%)'),
  line('Disputes:', String(cur.disputes)),
  '',
  flags.length ? 'NEEDS ATTENTION\n- ' + flags.join('\n- ') : 'No issues found.'
].join('\n');

return [{ json: { health, report } }];
